function applyMaskToCanvas(canvasCtx,canvas,mask,r){
  if(!canvasCtx||!mask)return;
  var type=str(mask.type,'rect').toLowerCase(),x=num(mask.x),y=num(mask.y),w=Math.max(0,num(mask.w)),h=Math.max(0,num(mask.h)),g=canvasCtx;
  g.save();
  try{
    var op=mask.invert?'destination-out':'destination-in';
    g.globalCompositeOperation=op;
    g.globalAlpha=1;
    if(type==='texture'&&mask.texture){
      var t=textureRecord(mask.texture);
      if(t&&Number(t.pid)===Number(r.pid)&&t.image)g.drawImage(t.image,0,0,t.width,t.height,x,y,w||t.width,h||t.height);
    }else{
      g.beginPath();
      if(type==='circle')g.arc(x,y,Math.max(0,num(mask.r,Math.min(w,h)/2)),0,Math.PI*2);
      else if(type==='ellipse'&&g.ellipse)g.ellipse(x,y,Math.max(0,num(mask.rx,w/2)),Math.max(0,num(mask.ry,h/2)),num(mask.rotation),0,Math.PI*2);
      else if(type==='roundrect')pathRoundRect(g,x,y,w,h,num(mask.radius,8));
      else if(type==='poly'||type==='polygon'){
        var pts=normalizePhysicsPolygon(mask.points||[]);
        if(pts.length>=3){g.moveTo(pts[0].x,pts[0].y);for(var i=1;i<pts.length;i++)g.lineTo(pts[i].x,pts[i].y);g.closePath();}
      }else g.rect(x,y,w,h);
      g.fill();
    }
  }finally{g.restore();}
}
function drawCommandWithEffects(r,c,camX,camY){
  var maskHandle=parseInt(c.mask,10)||0,filterHandle=parseInt(c.filterStack||c.filter,10)||0;
  var mask=maskHandle?v15owned(SDK.masks,{pid:r.pid},maskHandle,'Mask'):null;
  var filter=filterHandle?v15owned(SDK.filters,{pid:r.pid},filterHandle,'FilterStack'):null;
  if(!mask&&!filter)return false;
  var cv=global.document.createElement('canvas');cv.width=r.width;cv.height=r.height;
  var cg=cv.getContext('2d',{alpha:true});
  var rr={canvas:cv,g:cg,width:r.width,height:r.height,pid:r.pid,handle:r.handle,pixelated:r.pixelated,raster:r.raster,rasterScratch:null};
  var inner=v15clone(c);delete inner.mask;delete inner.filter;delete inner.filterStack;
  drawCommand(rr,inner,camX,camY);
  if(mask)applyMaskToCanvas(cg,cv,mask,r);
  r.g.save();
  if(filter)applyCanvasFilter(r.g,filter.filters);
  try{r.g.drawImage(cv,0,0);}catch(ignore){}
  r.g.restore();
  return true;
}
