/* Dialogue conditions / choices / commands */
function setDialogueVariables(ctx,h,vars){var r=ownedRecord(SDK.dialogues,ctx,h,'DialogueSystem');r.variables=v13clone(Object.assign({},r.variables||{},vars||{}));return v13clone(r.variables);}
