function executeDialogueCommands(ctx,h,commands){var r=ownedRecord(SDK.dialogues,ctx,h,'DialogueSystem'),arr=Array.isArray(commands)?commands:[],events=[];for(var i=0;i<arr.length;i++){var c=arr[i]||{};if(c.type==='set'&&c.var)(r.variables||(r.variables={}))[c.var]=v13clone(c.value);else if(c.type==='inc'&&c.var)(r.variables||(r.variables={}))[c.var]=num(r.variables[c.var])+num(c.value,1);else events.push(v13clone(c));}return{variables:v13clone(r.variables||{}),events:events};}

/* Save slots + metadata */
