function getDenominatorGapReport(){
  var matrix=getAllSDKComparisonMatrix(),extra=getDenominatorFeatureGapReportV20(),open=[],covered=[];
  for(var i=0;i<matrix.rows.length;i++){
    var r=matrix.rows[i],ok=Array.isArray(r.exos)&&r.exos.length>0;
    (ok?covered:open).push({feature:r.feature,exos:r.exos||[]});
  }
  for(var ei=0;ei<extra.added.length;ei++)covered.push(extra.added[ei]);
  return{version:SDK.version,build:SDK.build,status:open.length?'partial':'covered',covered:covered,open:open,notes:['EXOS Game2D exposes the requested web-engine and legacy-console concepts through process-owned handles and render commands.','Browser-only hardware access is modeled as portable resources: palette RAM, OAM, DMA, VBlank, command lists and raster effects are simulated, not native console registers.']};
}
