function analyzeLegacySpriteLimits(ctx,profile,opt){
  var p=assertLegacyProfile(ctx,profile),q=opt&&typeof opt==='object'?opt:{},viewport=q.viewport&&typeof q.viewport==='object'?q.viewport:p.display,perLine={},total=0,warnings=[],tables=[],k,r,s,y0,y1,y;
  for(k in V18.legacySpriteTables)if(own(V18.legacySpriteTables,k)){r=V18.legacySpriteTables[k];if(Number(r.pid)===Number(ctx.pid)&&Number(r.profile)===Number(p.handle))tables.push(r);}
  for(var ti=0;ti<tables.length;ti++){r=tables[ti];for(var i=0;i<r.sprites.length;i++){s=r.sprites[i];if(!s||s.visible===false)continue;total++;y0=Math.max(0,Math.floor(num(s.y)));y1=Math.min(Math.floor(num(viewport.height||viewport.h||p.display.height))-1,Math.ceil(num(s.y)+Math.max(1,num(s.h)))-1);for(y=y0;y<=y1;y++)perLine[String(y)]=(perLine[String(y)]||0)+1;}}
  if(total>p.limits.maxSprites)warnings.push({type:'MAX_SPRITES',count:total,limit:p.limits.maxSprites});
  var maxLine=0,maxLineY=0,overflow=[];
  for(k in perLine)if(own(perLine,k)){var c=perLine[k];if(c>maxLine){maxLine=c;maxLineY=parseInt(k,10)||0;}if(c>p.limits.maxSpritesPerLine)overflow.push({line:parseInt(k,10)||0,count:c,limit:p.limits.maxSpritesPerLine});}
  if(overflow.length)warnings.push({type:'SPRITES_PER_LINE',lines:overflow.slice(0,64),overflowLines:overflow.length});
  return{profile:p.handle,preset:p.preset,totalSprites:total,maxSprites:p.limits.maxSprites,maxSpritesOnLine:maxLine,maxSpritesOnLineY:maxLineY,maxSpritesPerLine:p.limits.maxSpritesPerLine,overflowLines:overflow.length,warnings:warnings};
}
