  for(k in V18.legacyOrderingTables)if(own(V18.legacyOrderingTables,k)){r=V18.legacyOrderingTables[k];if(Number(r.pid)===Number(ctx.pid)&&Number(r.profile)===Number(p.handle))ordering=ordering.concat(buildLegacyOrderingTableCommands(ctx,r.handle,!!q.clearOrderingTables));}
  for(k in V18.legacyCommandLists)if(own(V18.legacyCommandLists,k)){r=V18.legacyCommandLists[k];if(Number(r.pid)===Number(ctx.pid)&&Number(r.profile)===Number(p.handle))commandLists=commandLists.concat(buildLegacyCommandList(ctx,r.handle,!!q.clearCommandLists));}
