/* V25 Denominator: developer-platform layer.
 * Goal: solve recurring game-dev pain points without forcing a specific renderer,
 * editor or physics backend. Everything remains process-owned and serializable.
 */
var V25={
  next:0x8200,apps:{},traces:{},watches:{},rebinds:{},rollbacks:{},variants:{},saveTx:{},patches:{}
};
function v25id(){return ++V25.next;}
function v25clone(v){if(v===undefined||v===null||typeof v!=='object')return v;try{return JSON.parse(JSON.stringify(v));}catch(e){return String(v);}}
