  var q=spec&&typeof spec==='object'?spec:{},id=v25id(),r={handle:id,pid:Number(ctx.pid)||0,name:str(q.name,'EXOSApp'+id),phase:'boot',running:false,frame:0,elapsed:0,fixedStep:Math.max(.001,num(q.fixedStep,1/60)),maxCatchUp:Math.max(1,Math.min(16,parseInt(q.maxCatchUp,10)||8)),timeScale:Math.max(0,num(q.timeScale,1)),deterministic:q.deterministic!==false,services:{},metrics:{updates:0,fixedUpdates:0,renders:0,droppedSteps:0},events:[]};
