function rollbackGetState(ctx,h,frame){var r=v25owned(V25.rollbacks,ctx,h,'NetworkRollback'),f=parseInt(frame,10);if(!isFinite(f))f=r.frame;return{frame:f,input:v25clone(r.inputs[String(f)]),state:v25clone(r.states[String(f)]&&r.states[String(f)].state),confirmed:r.confirmed,latestFrame:r.frame};}
