/* Asset variants: solve “same game, different quality/device/locale” duplication. */
function createAssetVariantTable(ctx,spec){var q=spec&&typeof spec==='object'?spec:{},id=v25id(),r={handle:id,pid:Number(ctx.pid)||0,name:str(q.name,'Variants'+id),rules:v25clone(q.rules||{}),fallback:str(q.fallback,'default')};V25.variants[String(id)]=r;return{handle:id,name:r.name,fallback:r.fallback};}
function assetVariantSet(ctx,h,asset,variant,value){var r=v25owned(V25.variants,ctx,h,'AssetVariantTable'),a=str(asset,''),v=str(variant,'default');if(!a)throw new Error('STATUS_INVALID_PARAMETER: asset key is empty.');if(!r.rules[a])r.rules[a]={};r.rules[a][v]=v25clone(value);return{asset:a,variant:v,value:v25clone(value)};}
function assetVariantResolve(ctx,h,asset,profile){var r=v25owned(V25.variants,ctx,h,'AssetVariantTable'),a=str(asset,''),p=profile&&typeof profile==='object'?profile:{},rule=r.rules[a]||{},order=[];if(p.quality)order.push('quality:'+p.quality);if(p.device)order.push('device:'+p.device);if(p.locale)order.push('locale:'+p.locale);order.push(str(p.variant,''),r.fallback,'default');for(var i=0;i<order.length;i++){if(order[i]&&own(rule,order[i]))return{asset:a,variant:order[i],value:v25clone(rule[order[i]])};}var keys=Object.keys(rule);return{asset:a,variant:keys.length?keys[0]:null,value:keys.length?v25clone(rule[keys[0]]):null};}
