/* Transactional saves: no half-written save slot after a crash. */
function createSaveTransaction(ctx,spec){var q=spec&&typeof spec==='object'?spec:{},id=v25id(),r={handle:id,pid:Number(ctx.pid)||0,name:str(q.name,'SaveTx'+id),version:parseInt(q.version,10)||1,staged:null,committed:null,status:'idle'};V25.saveTx[String(id)]=r;return v25clone(r);}
function saveTxStage(ctx,h,data){var r=v25owned(V25.saveTx,ctx,h,'SaveTransaction');r.staged=v25clone(data);r.status='staged';return{status:r.status,version:r.version};}
function saveTxCommit(ctx,h,checksum){var r=v25owned(V25.saveTx,ctx,h,'SaveTransaction');if(r.staged===null)throw new Error('STATUS_INVALID_STATE: no staged save.');r.committed=v25clone(r.staged);r.staged=null;r.status='committed';r.checksum=checksum===undefined?v22hashString(JSON.stringify(r.committed)):str(checksum);return{status:r.status,version:r.version,checksum:r.checksum,data:v25clone(r.committed)};}
function saveTxAbort(ctx,h){var r=v25owned(V25.saveTx,ctx,h,'SaveTransaction');r.staged=null;r.status='aborted';return{status:r.status};}
function saveTxRead(ctx,h){var r=v25owned(V25.saveTx,ctx,h,'SaveTransaction');return{status:r.status,version:r.version,checksum:r.checksum||null,data:v25clone(r.committed)};}
function destroySaveTransaction(ctx,h){var r=v25owned(V25.saveTx,ctx,h,'SaveTransaction');delete V25.saveTx[String(r.handle)];return true;}

/* Live patch manager: apply named data/function patches atomically at a frame boundary. */
function createLivePatchManager(ctx,spec){var q=spec&&typeof spec==='object'?spec:{},id=v25id(),r={handle:id,pid:Number(ctx.pid)||0,name:str(q.name,'LivePatch'+id),pending:[],applied:[],next:0};V25.patches[String(id)]=r;return{handle:id,name:r.name};}
function livePatchQueue(ctx,h,name,patch){var r=v25owned(V25.patches,ctx,h,'LivePatchManager'),p={id:++r.next,name:str(name,'patch'),patch:v25clone(patch),queuedAt:r.applied.length};r.pending.push(p);return{queued:p.id,name:p.name};}
function livePatchApply(ctx,h){var r=v25owned(V25.patches,ctx,h,'LivePatchManager'),applied=r.pending.splice(0);for(var i=0;i<applied.length;i++){applied[i].applied=true;r.applied.push(applied[i]);}if(r.applied.length>256)r.applied=r.applied.slice(-256);return{applied:v25clone(applied),total:r.applied.length};}
function livePatchList(ctx,h){var r=v25owned(V25.patches,ctx,h,'LivePatchManager');return{pending:v25clone(r.pending),applied:v25clone(r.applied)};}
function destroyLivePatchManager(ctx,h){var r=v25owned(V25.patches,ctx,h,'LivePatchManager');delete V25.patches[String(r.handle)];return true;}

function getDeveloperPainPointReportV25(){return{version:25,targets:[
  {id:'DX18',problem:'Every game boot wires the same subsystems differently',solution:'GameApp gives explicit boot/preload/ready/running/paused/recovering phases.'},
  {id:'DX19',problem:'Crashes are visible but the few seconds before them are lost',solution:'TraceSession keeps bounded breadcrumbs and timestamped markers.'},
  {id:'DX20',problem:'Debugging needs scattered console.log statements',solution:'WatchTable exposes named live values to any inspector/debug UI.'},
  {id:'DX21',problem:'Players ask for controls remapping but bindings conflict',solution:'InputRebindProfile centralizes rebinding and conflict analysis.'},
  {id:'DX22',problem:'Online correction causes state jumps and hard-to-reproduce desyncs',solution:'NetworkRollback stores bounded input/state history and correction anchors.'},
  {id:'DX23',problem:'High/low quality assets multiply the project complexity',solution:'AssetVariantTable resolves profile-aware asset variants with fallback.'},
  {id:'DX24',problem:'A crash during save can corrupt the last good slot',solution:'SaveTransaction stages and commits atomically from the game logic side.'},
  {id:'DX25',problem:'Hot patching gameplay during development is unsafe or non-deterministic',solution:'LivePatchManager queues named patches and applies them at explicit boundaries.'}
],designRule:'Developer ergonomics is a first-class subsystem: boot determinism, observability, safe mutation, input compatibility, rollback and content variants are all renderer-independent.'};}

function cleanupV25Process(pid){var tables=[V25.apps,V25.traces,V25.watches,V25.rebinds,V25.rollbacks,V25.variants,V25.saveTx,V25.patches];for(var i=0;i<tables.length;i++){var t=tables[i];for(var k in t)if(own(t,k)&&Number(t[k].pid)===Number(pid))delete t[k];}return true;}


/* ============================================================================
 * DENOMINATOR V26 / UNIVERSAL GAME-DEVELOPMENT PLATFORM LAYER
 *
 * V26 focuses on the remaining friction between a large capability surface and
 * a pleasant day-to-day game-dev workflow. It is deliberately renderer- and
 * backend-neutral. It also makes the retro-console comparison explicit without
 * pretending that a browser can drive original SNES/PS1/MD/Saturn hardware.
 * ==========================================================================*/
var V26={
  next:0xB000,
  kits:{},inputContexts:{},sceneTransitions:{},frameHealth:{},crashReports:{},logRouters:{},
  mathProfiles:{},contentChecks:{},retroProfiles:{},featureFlags:{}
};
function v26id(){return ++V26.next;}
function v26rec(table,ctx,h,name){var r=table[String(parseInt(h,10)||0)];if(!r)throw new Error('STATUS_INVALID_HANDLE: invalid '+name+'.');if(ctx&&Number(r.pid)!==Number(ctx.pid))throw new Error('STATUS_ACCESS_DENIED: '+name+' ownership.');return r;}
function v26clone(v){if(v===undefined)return null;try{return JSON.parse(JSON.stringify(v));}catch(e){return v;}}

/* High-level kit: common boot path with explicit ownership and built-in DX. */
function createGameKit(ctx,spec){
  var q=spec&&typeof spec==='object'?spec:{},id=v26id(),
      project=createGameProject(ctx,{name:q.name||'EXOS Game',version:q.version||'1.0.0',target:q.target||'web',logicalWidth:q.logicalWidth||320,logicalHeight:q.logicalHeight||180,designWidth:q.designWidth||q.logicalWidth||320,designHeight:q.designHeight||q.logicalHeight||180,fixedStep:q.fixedStep||1/60,deterministic:q.deterministic!==false,pixelArt:!!q.pixelArt,backend:q.backend||'auto',modules:q.modules||[],features:q.features||{},metadata:q.metadata||{}}),
      app=createGameApp(ctx,{name:q.name||'GameApp',version:q.version||'1.0.0',phase:q.phase||'boot'}),
      clock=createGameClock(ctx,{fixedStep:q.fixedStep||1/60,deterministic:q.deterministic!==false,timeScale:q.timeScale===undefined?1:q.timeScale}),
      trace=createTraceSession(ctx,{name:'KitTrace',capacity:q.traceCapacity||256}),
      watch=createWatchTable(ctx,{name:'KitWatch'}),
      timeline=createStateTimeline(ctx,{name:'KitTimeline',capacity:q.timelineCapacity||120}),
      math=createDeterministicMathProfile(ctx,{mode:q.mathMode||((q.target||'web')==='retro'?'fixed16.16':'float'),quantum:q.mathQuantum}),
      crash=createCrashReporter(ctx,{name:'KitCrash',maxBreadcrumbs:q.maxBreadcrumbs||256});
  var r={handle:id,pid:Number(ctx.pid)||0,name:str(q.name,'EXOS Game Kit'),project:project.handle,app:app.handle,clock:clock.handle,trace:trace.handle,watch:watch.handle,math:math.handle,crash:crash.handle,timeline:timeline.handle,createdAt:Date.now(),activeScene:0};
  V26.kits[String(id)]=r;return v26clone(r);
}
function gameKitCreateScene(ctx,h,spec){var r=v26rec(V26.kits,ctx,h,'GameKit'),q=spec&&typeof spec==='object'?spec:{},surface=parseInt(q.surface,10)||0;if(!surface){var keys=Object.keys(SDK.surfaces).filter(function(k){return SDK.surfaces[k]&&Number(SDK.surfaces[k].pid)===Number(ctx.pid);});surface=keys.length?parseInt(keys[0],10):0;}if(!surface)throw new Error('STATUS_INVALID_STATE: GameKit needs a Surface before creating a Scene.');q.surface=surface;var scene=createScene(ctx,surface,q);r.activeScene=scene.handle;return scene;}
function gameKitSetScene(ctx,h,sceneHandle){var r=v26rec(V26.kits,ctx,h,'GameKit'),scene=v15owned(SDK.scenes,ctx,sceneHandle,'Scene');r.activeScene=scene.handle;return{kit:r.handle,scene:scene.handle,name:scene.name};}
function gameKitSpawn(ctx,h,spec){var r=v26rec(V26.kits,ctx,h,'GameKit');if(!r.activeScene)throw new Error('STATUS_INVALID_STATE: GameKit has no active Scene.');return createGameObject2D(ctx,r.activeScene,spec||{});}
function gameKitSetState(ctx,h,key,value){var r=v26rec(V26.kits,ctx,h,'GameKit');return watchSet(ctx,r.watch,key,value,key);}
function gameKitGetState(ctx,h,key){var r=v26rec(V26.kits,ctx,h,'GameKit');return watchGet(ctx,r.watch,key);}
function gameKitStep(ctx,h,rawDt){var r=v26rec(V26.kits,ctx,h,'GameKit'),clock=stepGameClock(ctx,r.clock,rawDt),app=gameAppStep(ctx,r.app,rawDt),trace=traceStep(ctx,r.trace,rawDt);var out={kit:r.handle,clock:clock,app:app,trace:trace,scene:r.activeScene};if(r.activeScene){var scene=SDK.scenes[String(r.activeScene)];if(scene)scene.time+=num(clock.dt); } return out;}
function gameKitSnapshot(ctx,h,state,meta){var r=v26rec(V26.kits,ctx,h,'GameKit'),snap=createGameSnapshot(ctx,{include:{rng:true,performance:true,resources:true},state:state,userData:{kit:r.handle,activeScene:r.activeScene,meta:meta||null}});stateTimelineCapture(ctx,r.timeline,state,meta||{});return snap;}
function destroyGameKit(ctx,h){var r=v26rec(V26.kits,ctx,h,'GameKit');var pairs=[[V23.projects,r.project,'GameProject'],[V25.apps,r.app,'GameApp'],[V20.clocks,r.clock,'GameClock'],[V25.traces,r.trace,'TraceSession'],[V25.watches,r.watch,'WatchTable'],[V26.mathProfiles,r.math,'DeterministicMathProfile'],[V26.crashReports,r.crash,'CrashReporter'],[V24.stateTimelines,r.timeline,'StateTimeline']];for(var i=0;i<pairs.length;i++){try{if(pairs[i][0][String(pairs[i][1])])delete pairs[i][0][String(pairs[i][1])];}catch(ignore){}}delete V26.kits[String(r.handle)];return true;}

/* Input contexts: solve menu/gameplay/debug rebinding conflicts and focus leakage. */
function createInputContext(ctx,spec){var q=spec&&typeof spec==='object'?spec:{},id=v26id(),r={handle:id,pid:Number(ctx.pid)||0,name:str(q.name,'InputContext'+id),stack:Array.isArray(q.stack)?q.stack.map(String):[],contexts:q.contexts&&typeof q.contexts==='object'?v26clone(q.contexts):{},active:q.active===undefined?'game':str(q.active),enabled:q.enabled!==false,focusRequired:q.focusRequired!==false,deviceState:{keyboard:true,pointer:true,gamepad:true,touch:true},lostInputs:[],generation:0};V26.inputContexts[String(id)]=r;return v26clone(r);}
function inputContextDefine(ctx,h,name,bindings,options){var r=v26rec(V26.inputContexts,ctx,h,'InputContext'),n=str(name,'');if(!n)throw new Error('STATUS_INVALID_PARAMETER: input context name required.');r.contexts[n]={bindings:v26clone(bindings||{}),enabled:options&&options.enabled!==false};return{handle:r.handle,name:n,bindings:Object.keys(r.contexts[n].bindings)};}
function inputContextPush(ctx,h,name){var r=v26rec(V26.inputContexts,ctx,h,'InputContext'),n=str(name,'');if(!r.contexts[n])throw new Error('STATUS_NOT_FOUND: input context not defined.');r.stack.push(r.active);r.active=n;return{active:r.active,depth:r.stack.length};}
function inputContextPop(ctx,h){var r=v26rec(V26.inputContexts,ctx,h,'InputContext');if(r.stack.length)r.active=r.stack.pop();return{active:r.active,depth:r.stack.length};}
function inputContextSetActive(ctx,h,name){var r=v26rec(V26.inputContexts,ctx,h,'InputContext'),n=str(name,'');if(!r.contexts[n])throw new Error('STATUS_NOT_FOUND: input context not defined.');r.active=n;return{active:r.active};}
function inputContextDeviceEvent(ctx,h,type,spec){var r=v26rec(V26.inputContexts,ctx,h,'InputContext'),q=spec&&typeof spec==='object'?spec:{},t=str(type,'device');if(t==='disconnect'||t==='connect'){var d=str(q.device,'gamepad');r.deviceState[d]=t==='connect';if(t==='disconnect')r.lostInputs.push({device:d,time:Date.now(),generation:++r.generation});}if(t==='focus')r.focused=q.focused!==false;if(t==='blur')r.focused=false;return{active:r.active,deviceState:v26clone(r.deviceState),generation:r.generation};}
function inputContextGet(ctx,h){var r=v26rec(V26.inputContexts,ctx,h,'InputContext');return v26clone(r);}
function destroyInputContext(ctx,h){var r=v26rec(V26.inputContexts,ctx,h,'InputContext');delete V26.inputContexts[String(r.handle)];return true;}

/* Transactional scene changes: prepare -> commit, with explicit failure path. */
function createSceneTransition(ctx,spec){var q=spec&&typeof spec==='object'?spec:{},id=v26id(),r={handle:id,pid:Number(ctx.pid)||0,name:str(q.name,'SceneTransition'+id),state:'idle',from:0,to:0,progress:0,duration:Math.max(.001,num(q.duration,.25)),elapsed:0,error:null,meta:v26clone(q.meta||{})};V26.sceneTransitions[String(id)]=r;return v26clone(r);}
function sceneTransitionPrepare(ctx,h,from,to,meta){var r=v26rec(V26.sceneTransitions,ctx,h,'SceneTransition');r.from=parseInt(from,10)||0;r.to=parseInt(to,10)||0;r.progress=0;r.elapsed=0;r.error=null;r.meta=v26clone(meta||r.meta||{});r.state='prepared';return v26clone(r);}
function sceneTransitionCommit(ctx,h){var r=v26rec(V26.sceneTransitions,ctx,h,'SceneTransition');if(r.state!=='prepared'&&r.state!=='running')throw new Error('STATUS_INVALID_STATE: SceneTransition is not prepared.');r.state='committed';r.progress=1;r.elapsed=r.duration;return v26clone(r);}
function sceneTransitionAbort(ctx,h,error){var r=v26rec(V26.sceneTransitions,ctx,h,'SceneTransition');r.state='aborted';r.error=str(error,'aborted');return v26clone(r);}
function sceneTransitionStep(ctx,h,dt){var r=v26rec(V26.sceneTransitions,ctx,h,'SceneTransition'),d=Math.max(0,num(dt));if(r.state==='prepared')r.state='running';if(r.state==='running'){r.elapsed=Math.min(r.duration,r.elapsed+d);r.progress=clamp(r.elapsed/r.duration,0,1);if(r.progress>=1)r.state='committed';}return v26clone(r);}
function destroySceneTransition(ctx,h){var r=v26rec(V26.sceneTransitions,ctx,h,'SceneTransition');delete V26.sceneTransitions[String(r.handle)];return true;}

/* Frame health: detect jank instead of merely reporting average FPS. */
function createFrameHealth(ctx,spec){var q=spec&&typeof spec==='object'?spec:{},id=v26id(),r={handle:id,pid:Number(ctx.pid)||0,name:str(q.name,'FrameHealth'+id),targetFps:Math.max(1,num(q.targetFps,60)),window:Math.max(8,Math.min(240,parseInt(q.window,10)||60)),hitchMultiplier:Math.max(1.1,num(q.hitchMultiplier,2)),samples:[],frame:0,jankFrames:0,droppedFrames:0,maxDt:0,totalDt:0};V26.frameHealth[String(id)]=r;return{handle:id,name:r.name,targetFps:r.targetFps,window:r.window};}
function frameHealthAdd(ctx,h,dt){var r=v26rec(V26.frameHealth,ctx,h,'FrameHealth'),d=Math.max(0,num(dt)),budget=1/r.targetFps,ratio=budget?d/budget:0;r.frame++;r.totalDt+=d;r.maxDt=Math.max(r.maxDt,d);r.samples.push(d);if(r.samples.length>r.window)r.samples.shift();if(ratio>=r.hitchMultiplier)r.jankFrames++;if(ratio>1.25)r.droppedFrames+=Math.max(0,Math.round(ratio)-1);return{frame:r.frame,dt:d,ratio:ratio,jank:ratio>=r.hitchMultiplier,avgDt:r.samples.reduce(function(a,b){return a+b;},0)/Math.max(1,r.samples.length),fps:d>0?1/d:0};}
function frameHealthReport(ctx,h){var r=v26rec(V26.frameHealth,ctx,h,'FrameHealth'),avg=r.samples.reduce(function(a,b){return a+b;},0)/Math.max(1,r.samples.length);return{handle:r.handle,name:r.name,targetFps:r.targetFps,window:r.window,frames:r.frame,jankFrames:r.jankFrames,droppedFrames:r.droppedFrames,maxDt:r.maxDt,avgDt:avg,avgFps:avg>0?1/avg:0,jankRate:r.frame?r.jankFrames/r.frame:0};}
function destroyFrameHealth(ctx,h){var r=v26rec(V26.frameHealth,ctx,h,'FrameHealth');delete V26.frameHealth[String(r.handle)];return true;}

/* Crash report bundle: one copy/pasteable artifact from the failure boundary. */
function createCrashReporter(ctx,spec){var q=spec&&typeof spec==='object'?spec:{},id=v26id(),r={handle:id,pid:Number(ctx.pid)||0,name:str(q.name,'CrashReporter'+id),maxBreadcrumbs:Math.max(32,Math.min(4096,parseInt(q.maxBreadcrumbs,10)||256)),breadcrumbs:[],last:null};V26.crashReports[String(id)]=r;return{handle:id,name:r.name,maxBreadcrumbs:r.maxBreadcrumbs};}
function crashBreadcrumb(ctx,h,type,data){var r=v26rec(V26.crashReports,ctx,h,'CrashReporter');r.breadcrumbs.push({time:Date.now(),type:str(type,'event'),data:v26clone(data)});while(r.breadcrumbs.length>r.maxBreadcrumbs)r.breadcrumbs.shift();return{count:r.breadcrumbs.length};}
function captureCrashReport(ctx,h,error,state,meta){var r=v26rec(V26.crashReports,ctx,h,'CrashReporter'),msg=error&&error.message?error.message:str(error,'Unknown error'),stack=error&&error.stack?String(error.stack):null,rpt={version:'EXOS-CRASH-V1',time:new Date().toISOString(),sdk:{version:SDK.version,build:SDK.build,apiVersion:SDK.apiVersion,model:SDK.model},pid:Number(ctx.pid)||0,error:{message:msg,stack:stack},stateHash:state===undefined?null:hashGameState(state).hash,state:state===undefined?null:v26clone(state),meta:meta===undefined?null:v26clone(meta),breadcrumbs:v26clone(r.breadcrumbs)};r.last=rpt;return v26clone(rpt);}
function getCrashReport(ctx,h){var r=v26rec(V26.crashReports,ctx,h,'CrashReporter');return v26clone(r.last);}
function clearCrashReport(ctx,h){var r=v26rec(V26.crashReports,ctx,h,'CrashReporter');r.last=null;r.breadcrumbs=[];return true;}
function destroyCrashReporter(ctx,h){var r=v26rec(V26.crashReports,ctx,h,'CrashReporter');delete V26.crashReports[String(r.handle)];return true;}

/* Log router: levels, once-only and rate-limit without littering gameplay code. */
function createLogRouter(ctx,spec){var q=spec&&typeof spec==='object'?spec:{},id=v26id(),r={handle:id,pid:Number(ctx.pid)||0,name:str(q.name,'LogRouter'+id),level:str(q.level,'debug').toLowerCase(),events:[],once:{},counts:{},max:Math.max(32,Math.min(4096,parseInt(q.max,10)||512))};V26.logRouters[String(id)]=r;return{handle:id,name:r.name,level:r.level};}
function logAllowed(level,current){var order={trace:0,debug:1,info:2,warn:3,error:4,silent:99};var a=order[str(level,'info').toLowerCase()];var b=order[str(current,'debug').toLowerCase()];return (a===undefined?2:a)>=(b===undefined?1:b);}
function logWrite(ctx,h,level,message,data,options){var r=v26rec(V26.logRouters,ctx,h,'LogRouter'),lv=str(level,'info').toLowerCase(),o=options&&typeof options==='object'?options:{},key=str(o.key,message);if(!logAllowed(lv,r.level))return{logged:false,reason:'level'};if(o.once&&r.once[key])return{logged:false,reason:'once'};if(o.once)r.once[key]=true;r.counts[key]=(r.counts[key]||0)+1;var e={seq:r.events.length+1,time:new Date().toISOString(),level:lv,message:str(message),data:v26clone(data),count:r.counts[key]};r.events.push(e);while(r.events.length>r.max)r.events.shift();return{logged:true,event:v26clone(e)};}
function logSnapshot(ctx,h){var r=v26rec(V26.logRouters,ctx,h,'LogRouter');return{handle:r.handle,name:r.name,level:r.level,count:r.events.length,events:v26clone(r.events),counts:v26clone(r.counts)};}
function destroyLogRouter(ctx,h){var r=v26rec(V26.logRouters,ctx,h,'LogRouter');delete V26.logRouters[String(r.handle)];return true;}

/* Deterministic math: fixed-point + quantization for replay/retro portability. */
function createDeterministicMathProfile(ctx,spec){var q=spec&&typeof spec==='object'?spec:{},id=v26id(),mode=str(q.mode,'float').toLowerCase(),quantum=q.quantum===undefined?(mode==='fixed16.16'?1/65536:0):Math.max(0,num(q.quantum)),r={handle:id,pid:Number(ctx.pid)||0,name:str(q.name,'Math'+id),mode:mode==='fixed16.16'||mode==='fixed8.8' ? mode:'float',fractionBits:mode==='fixed8.8'?8:16,quantum:quantum};V26.mathProfiles[String(id)]=r;return v26clone(r);}
function mathEncode(ctx,h,value){var r=v26rec(V26.mathProfiles,ctx,h,'DeterministicMathProfile'),v=num(value);if(r.mode==='float'&&r.quantum<=0)return v;if(r.mode==='fixed8.8')return Math.round(v*256)/256;if(r.mode==='fixed16.16')return Math.round(v*65536)/65536;return r.quantum>0?Math.round(v/r.quantum)*r.quantum:v;}
