function mathLerp(ctx,h,a,b,t){return mathEncode(ctx,h,num(a)+(num(b)-num(a))*clamp(t,0,1));}
function mathQuantizeAngle(ctx,h,rad,steps){var n=Math.max(1,Math.round(num(steps,256))),unit=(Math.PI*2)/n;return mathEncode(ctx,h,Math.round(num(rad)/unit)*unit);}
