/* Explicit retro target profiles: timing/resource limits are treated as validation targets. */
function createRetroProfile(ctx,spec){var q=spec&&typeof spec==='object'?spec:{},id=v26id(),platform=str(q.platform,'sfc').toLowerCase(),defaults={sfc:{family:'SNES/SFC',resolution:[256,224],fps:60,vram:64*1024,oamEntries:128,colorsPerPalette:16,paletteBanks:8,spritesPerLine:32,notes:['Tile/background-first architecture','Mode 7 available as a specialized display mode']},ps1:{family:'Sony PlayStation',resolution:[320,240],fps:60,vram:1024*1024,orderingTable:4096,gpuPrimitives:true,gte:true,notes:['GPU packet / ordering-table style rendering','Fixed-point friendly math']},md:{family:'Sega Mega Drive',resolution:[320,224],fps:60,vram:64*1024,cramBytes:128,vsram:80,maxSprites:80,maxSpritesPerLine:20,notes:['VDP tile-plane architecture','DMA/VBlank scheduling is central']},ss:{family:'Sega Saturn',resolution:[320,224],fps:60,vram:1024*1024,cramBytes:1024,vdP1CommandBudget:2048,vdP2Planes:4,notes:['VDP1 command lists','VDP2 scrolling/tile layers']}};var d=defaults[platform]||defaults.sfc,r={handle:id,pid:Number(ctx.pid)||0,name:str(q.name,d.family+' Profile'),platform:platform,limits:v26clone(d),used:q.used&&typeof q.used==='object'?v26clone(q.used):{},warnings:[],strict:q.strict!==false};V26.retroProfiles[String(id)]=r;return v26clone(r);}
function retroProfileValidate(ctx,h,usage){var r=v26rec(V26.retroProfiles,ctx,h,'RetroProfile'),u=usage&&typeof usage==='object'?usage:r.used,issues=[],k,limit,val,ratio;for(k in r.limits)if(own(r.limits,k)&&typeof r.limits[k]==='number'&&u[k]!==undefined){limit=r.limits[k];val=num(u[k]);ratio=val/Math.max(1,limit);if(val>limit)issues.push({code:'LIMIT_EXCEEDED',field:k,value:val,limit:limit,severity:'error'});else if(ratio>=0.8)issues.push({code:'LIMIT_NEAR',field:k,value:val,limit:limit,ratio:ratio,severity:'warning'});}r.used=v26clone(u);r.warnings=issues;return{handle:r.handle,platform:r.platform,valid:issues.every(function(x){return x.severity!=='error';}),issues:issues,limits:v26clone(r.limits),used:v26clone(r.used)};}
