SDK.nextObjectWorld=0x7100; SDK.nextBehaviorTree=0x7200; SDK.nextAssetBundle=0x7300;
SDK.nextObjectPool=0x7400; SDK.nextFixedLoop=0x7500; SDK.nextActionMap=0x7600;
SDK.nextGameDoctor=0x7700;
