  var type=str(node.type,'action').toLowerCase(),i,res,child;
  if(type==='condition'){try{return node.test&&node.test(bb,dt,env)?'success':'failure';}catch(e){return'failure';}}
  if(type==='action'){try{return behaviorStatus(node.run?node.run(bb,dt,env):node.status||'success');}catch(e){bb.__error=String(e&&e.message||e);return'failure';}}
  if(type==='wait'){bb.__wait=(num(bb.__wait,0)+Math.max(0,num(dt)));return bb.__wait>=Math.max(0,num(node.duration,0))?'success':'running';}
  var children=Array.isArray(node.children)?node.children:[];
  if(type==='sequence'){for(i=0;i<children.length;i++){res=evalBehaviorNode(children[i],bb,dt,env);if(res!=='success')return res;}return'success';}
  if(type==='selector'){for(i=0;i<children.length;i++){res=evalBehaviorNode(children[i],bb,dt,env);if(res!=='failure')return res;}return'failure';}
  if(type==='parallel'){var anyRunning=false,successes=0;for(i=0;i<children.length;i++){res=evalBehaviorNode(children[i],bb,dt,env);if(res==='running')anyRunning=true;if(res==='success')successes++;}if(node.policy==='all')return successes===children.length?'success':(anyRunning?'running':'failure');return successes>0?'success':(anyRunning?'running':'failure');}
