  if(type==='repeat'){var count=Math.max(1,parseInt(node.count,10)||1);for(i=0;i<count;i++){res=evalBehaviorNode(children[0],bb,dt,env);if(res==='failure')return'failure';if(res==='running')return'running';}return'success';}
