cleanupProcess=function(pid){var ok=cleanupProcessV30(pid);cleanupV31Process(pid);return ok;};


/* ==========================================================================
 * V32 Universal Developer / Production Layer
 * --------------------------------------------------------------------------
 * This layer closes the most common game-development pain points:
 * deterministic ECS, behavior trees, rollback state plumbing, hot reload,
 * schema migration, asset linting, responsive UI layout, camera rigging,
 * input rebinding, structured diagnostics, and profiling.
 *
 * It is intentionally backend-neutral: these APIs describe the contracts,
 * data flow, budgets and debugging tools without pretending to expose
 * proprietary console hardware that a browser cannot access.
 * ========================================================================== */
var V32={
  devSessions:{}, profilers:{}, ecsWorlds:{}, behaviorTrees:{}, rollbackSessions:{},
  hotReloadStores:{}, schemaStores:{}, assetLints:{}, layouts:{}, cameraRigs:{}, inputProfiles:{},
  nextId:1
};
function v32id(){return 0x52000+(V32.nextId++);}
function v32own(map,ctx,h,name){var r=map[String(parseInt(h,10)||0)];if(!r)throw new Error('STATUS_INVALID_HANDLE: invalid '+name+'.');if(ctx&&Number(r.pid)!==Number(ctx.pid))throw new Error('STATUS_ACCESS_DENIED: '+name+' ownership.');return r;}
function v32clone(v){if(v===undefined)return undefined;try{return JSON.parse(JSON.stringify(v));}catch(e){throw new Error('STATUS_INVALID_PARAMETER: value is not serializable.');}}
function v32num(n,d){n=Number(n);return isFinite(n)?n:(d===undefined?0:d);}
function v32clamp(n,a,b){return Math.max(a,Math.min(b,n));}
function v32now(){return Date.now();}
function v32hash(v){var s;try{s=JSON.stringify(v);}catch(e){s=String(v);}var h=2166136261,i,c;for(i=0;i<s.length;i++){c=s.charCodeAt(i);h^=c;h=Math.imul(h,16777619);}return('00000000'+(h>>>0).toString(16)).slice(-8);}

/* -------- Structured developer diagnostics / profiling -------- */
function createDevSession(ctx,spec){
  var q=spec&&typeof spec==='object'?spec:{},id=v32id(),r={handle:id,pid:Number(ctx.pid)||0,name:String(q.name||'DevSession'+id),maxLogs:Math.max(64,parseInt(q.maxLogs,10)||4096),logs:[],marks:[],watches:{},enabled:q.enabled!==false};
  V32.devSessions[String(id)]=r;return{handle:id,name:r.name};
}
function devLog(ctx,h,level,message,data){
  var r=v32own(V32.devSessions,ctx,h,'DevSession'),item={time:v32now(),level:String(level||'info').toLowerCase(),message:String(message||''),data:v32clone(data)};
  r.logs.push(item);while(r.logs.length>r.maxLogs)r.logs.shift();return item;
}
function devMark(ctx,h,name,data){var r=v32own(V32.devSessions,ctx,h,'DevSession'),m={time:v32now(),name:String(name||'mark'),data:v32clone(data)};r.marks.push(m);if(r.marks.length>1024)r.marks.shift();return m;}
function devWatch(ctx,h,name,value){var r=v32own(V32.devSessions,ctx,h,'DevSession'),n=String(name||'watch');r.watches[n]={value:v32clone(value),updated:v32now(),hash:v32hash(value)};return v32clone(r.watches[n]);}
