/* -------- V32 reports / comparison matrix -------- */
function getDeveloperPainPointReportV32(){return{version:32,focus:'developer-experience-and-production-reliability',painPoints:[
  {id:'DX75',problem:'Projects duplicate gameplay architecture because scene graphs and object APIs do not guarantee a data-oriented path.',solution:'ECSWorld provides deterministic entities/components/system ordering without forcing a renderer or physics backend.'},
  {id:'DX76',problem:'AI prototypes become piles of bespoke if/else code and are hard to debug.',solution:'BehaviorTree provides data-driven sequence/selector/parallel/condition/action/wait primitives with a blackboard.'},
  {id:'DX77',problem:'Rollback netcode is expensive because input, snapshots and mismatch detection are rebuilt per project.',solution:'RollbackSession standardizes frame inputs, prediction flags, bounded snapshots and correction points.'},
  {id:'DX78',problem:'Hot reload often mutates live state with no revision or dependency visibility.',solution:'HotReloadStore versions modules, records invalidation/replace events and exposes the current revision.'},
  {id:'DX79',problem:'Save/schema changes silently break old data.',solution:'SchemaStore makes versions, validation and explicit migration steps first-class.'},
  {id:'DX80',problem:'Asset errors appear late at runtime: missing dependency, duplicates, cycles and oversized resources.',solution:'AssetLint performs preflight checks and returns machine-readable issues.'},
  {id:'DX81',problem:'Responsive UI breaks because each project reinvents anchors, safe areas and scaling.',solution:'ResponsiveLayout computes anchor-aware layout using viewport and safe-area constraints.'},
  {id:'DX82',problem:'Camera code mixes follow, dead-zone, bounds and shake logic in gameplay scripts.',solution:'CameraRig centralizes those policies and supports world/screen conversion.'},
  {id:'DX83',problem:'Input rebinding systems are harder to maintain than gameplay itself and often ship conflicting bindings.',solution:'InputProfile separates action vocabulary from device bindings and reports conflicts before shipping.'},
  {id:'DX84',problem:'A fast game can still be impossible to diagnose because logs lack timeline, counters and frame metrics.',solution:'DevSession + DevProfiler produce structured, bounded, machine-readable diagnostics.'}
],principles:['deterministic-first','data-oriented-when-useful','debuggability-is-a-feature','build-time-validation','safe-runtime-evolution','backend-neutral-contracts','retro-budget-awareness']};}
