async function assetStreamLoadOne(ctx,h,key){var r=v33own(V33.assetStreams,ctx,h,'AssetStream'),it=r.items[key];if(!it||it.status!=='queued')return it? v33clone(it):null;r.active++;it.status='loading';var controller=typeof global.AbortController==='function'?new global.AbortController():null;if(controller)r.controllers[key]=controller;var attempt=0,last=null;while(attempt<=it.retry){attempt++;it.attempts=attempt;try{var resp=await global.fetch(it.url,{credentials:(ctx&&ctx.assetCredentials)||'same-origin',signal:controller?controller.signal:undefined});if(!resp.ok)throw new Error('HTTP '+resp.status);var data;if(it.type==='text'||it.type==='json'){var txt=await resp.text();data=it.type==='json'?JSON.parse(txt):txt;it.size=txt.length;}else{data=await resp.arrayBuffer();it.size=data.byteLength;}it.data=data;it.status='loaded';it.error=null;r.done++;r.events.push({type:'loaded',id:key,attempt:attempt,size:it.size,time:Date.now()});delete r.controllers[key];r.active--;return v33clone({id:key,status:it.status,attempts:attempt,size:it.size});}catch(e){last=e;if(it.status==='cancelled')break;if(attempt>it.retry){it.status='error';it.error=String(e&&e.message||e);r.failed++;r.events.push({type:'error',id:key,attempt:attempt,error:it.error,time:Date.now()});}}}delete r.controllers[key];r.active--;return v33clone({id:key,status:it.status,attempts:it.attempts,error:it.error||null});}
