/* Fixed-step scheduler with explicit update phases and overrun reporting. */
function createFixedScheduler(ctx,spec){var q=spec&&typeof spec==='object'?spec:{},id=v33id(),hz=Math.max(1,Math.min(1000,parseInt(q.hz,10)||60));var r={handle:id,pid:Number(ctx.pid)||0,hz:hz,dt:1/hz,acc:0,time:0,frame:0,maxSubSteps:Math.max(1,Math.min(16,parseInt(q.maxSubSteps,10)||5)),paused:false,systems:{},order:[]};V33.fixedSchedulers[String(id)]=r;return{handle:id,hz:hz,dt:r.dt};}
