function fixedSchedulerStep(ctx,h,elapsed){var r=v33own(V33.fixedSchedulers,ctx,h,'FixedScheduler');var e=Math.max(0,Math.min(0.25,v33num(elapsed,0)));if(r.paused)return{frame:r.frame,steps:0,acc:r.acc,alpha:r.acc/r.dt,overrun:false};r.acc+=e;var steps=0,overrun=false;while(r.acc>=r.dt&&steps<r.maxSubSteps){var env={dt:r.dt,time:r.time,frame:r.frame+1};for(var i=0;i<r.order.length;i++){var sys=r.systems[r.order[i]];if(sys)try{sys.callback(env);}catch(err){env.error={system:sys.name,message:String(err&&err.message||err)};}}r.acc-=r.dt;r.time+=r.dt;r.frame++;steps++;}if(r.acc>=r.dt){overrun=true;r.acc=Math.min(r.acc,r.dt*0.999);}return{frame:r.frame,time:r.time,steps:steps,alpha:r.acc/r.dt,overrun:overrun};}
