/* V36 coverage/pain-point reports. */
function getDeveloperPainPointReportV36(){return{version:36,focus:'integration-hardening-and-real-game-production',
painPoints:[
{id:'DX112',problem:'Gameplay logic, transforms and renderer hierarchy become tangled.',solution:'EntityGraph separates logical parent/child relationships from renderer-specific objects and supports deterministic lifecycle queries.'},
{id:'DX113',problem:'Fast-moving bodies tunnel through thin colliders.',solution:'SweptCollisionToolkit provides continuous-lite swept AABB/circle tests that can be paired with the existing discrete physics world.'},
{id:'DX114',problem:'Keyboard, touch and gamepad code forks into separate gameplay implementations.',solution:'InputRouter normalizes devices into named actions with pressed/released/down semantics.'},
{id:'DX115',problem:'Audio ducking and music fades are rebuilt differently in every game.',solution:'AudioMixerGraph adds bus hierarchy, crossfade/fade and ducking policy independent of WebAudio/native backends.'},
{id:'DX116',problem:'Controller/keyboard-only UI navigation is hard to make consistent.',solution:'UIWidgetTree supplies standard widgets, focus management and directional navigation.'},
{id:'DX117',problem:'Deterministic bugs disappear before developers can compare a good and bad run.',solution:'DeterminismGuard provides canonical state checksums and reproducible RNG for frame-by-frame mismatch detection.'},
{id:'DX118',problem:'Frame hitches are reported as vague FPS drops instead of actionable budgets.',solution:'FrameDiagnostics records frame time, hitches, counters and rolling history.'},
{id:'DX119',problem:'Editor/runtime tools need undo/redo but gameplay state must stay serializable.',solution:'CommandHistory stores bounded reversible command records with no renderer dependency.'},
{id:'DX120',problem:'Data-driven projects suffer from missing references and accidental duplicate IDs.',solution:'ContentRegistry provides typed IDs, aliases, dependency validation and content checksums.'},
{id:'DX121',problem:'DPR, safe areas and orientation logic keep escaping into UI code.',solution:'DeviceProfile centralizes viewport/DPR/safe-area normalization and design-space computation.'},
{id:'DX122',problem:'Async scene/resource callbacks arrive after a transition was cancelled.',solution:'TransitionToken provides generation-based stale-callback rejection.'},
{id:'DX123',problem:'Destroyed resources still have live references and leak silently.',solution:'ResourceLifetimeTracker reports stale logical handles and owner metadata.'},
{id:'DX124',problem:'Gameplay regressions are difficult to reproduce in a browser build/CI.',solution:'GameTestSuite provides serializable assertions and reports compatible with deterministic replay/checksum workflows.'}
],
principles:['engine-neutral-core','renderer-separation','device-normalization','deterministic-debugging','bounded-memory','stale-callback-safety','data-driven-authoring','testable-runtime']};}
