/* ---------- V37: universal "why is this broken?" diagnostics ---------- */
function diagnoseGameObject(spec){
  var q=spec&&typeof spec==='object'?spec:{},issues=[],hints=[];
  if(q.visible===false)issues.push('OBJECT_INVISIBLE');if(q.active===false)issues.push('OBJECT_INACTIVE');
  if(q.parent===null||q.parent===undefined)issues.push('NO_PARENT_OR_SCENE');if(q.graphics===false)issues.push('NO_GRAPHICS');
  if(q.x!==undefined&&(!isFinite(Number(q.x))||!isFinite(Number(q.y||0))))issues.push('NON_FINITE_TRANSFORM');
  if(q.scale!==undefined&&Number(q.scale)===0)issues.push('ZERO_SCALE');
  if(q.alpha!==undefined&&Number(q.alpha)<=0)issues.push('ZERO_ALPHA');
  if(q.cameraVisible===false)issues.push('CULLED_BY_CAMERA');
  if(q.assetLoaded===false)issues.push('ASSET_NOT_LOADED');
  if(q.textureMissing===true)issues.push('TEXTURE_MISSING');
  if(q.zInvalid===true)issues.push('INVALID_RENDER_ORDER');
  if(issues.indexOf('NO_PARENT_OR_SCENE')>=0)hints.push('Attach the object to an active scene/display tree.');
  if(issues.indexOf('NO_GRAPHICS')>=0)hints.push('Assign a sprite/graphics/text component before rendering.');
  if(issues.indexOf('ASSET_NOT_LOADED')>=0)hints.push('Check the asset manifest, preload plan and cache key.');
  if(issues.indexOf('CULLED_BY_CAMERA')>=0)hints.push('Check world-to-screen coordinates, camera bounds and culling rectangle.');
  if(issues.indexOf('NON_FINITE_TRANSFORM')>=0)hints.push('Trace the last system that wrote position/scale/rotation.');
  return{ok:issues.length===0,issues:issues,hints:hints};
}
function diagnoseCollision(spec){
  var q=spec&&typeof spec==='object'?spec:{},issues=[],hints=[];
  if(q.tunneling)issues.push('TUNNELING');if(q.missedLayers)issues.push('LAYER_MASK_MISMATCH');if(q.missedCallback)issues.push('CALLBACK_NOT_BOUND');
  if(q.sensorRequired&&q.solidOnly)issues.push('SENSOR_SOLID_POLICY');
  if(q.tunneling)hints.push('Use swept collision / continuous collision checks and clamp maximum step size.');
  if(q.missedLayers)hints.push('Compare layer/category/mask bits on both bodies.');
  return{ok:issues.length===0,issues:issues,hints:hints};
}
function diagnoseInput(spec){
  var q=spec&&typeof spec==='object'?spec:{},issues=[],hints=[];
  if(q.contextMissing)issues.push('INPUT_CONTEXT_MISSING');if(q.bindingConflict)issues.push('BINDING_CONFLICT');if(q.focusLost)issues.push('FOCUS_LOST');
  if(q.pointerBlocked)issues.push('POINTER_BLOCKED');if(q.gestureNotStarted)issues.push('GESTURE_NOT_STARTED');
  if(q.contextMissing)hints.push('Inspect the active input context stack and action binding resolution.');
  if(q.bindingConflict)hints.push('Run input conflict detection and remove ambiguous bindings.');
  if(q.focusLost)hints.push('Restore canvas/window focus before consuming keyboard or gamepad events.');
  return{ok:issues.length===0,issues:issues,hints:hints};
}
function diagnoseFrame(spec){
  var q=spec&&typeof spec==='object'?spec:{},issues=[],hints=[],budget=Number(q.budgetMs||16.666),frame=Number(q.frameMs||0);
  if(frame>budget)issues.push('FRAME_BUDGET_EXCEEDED');
  if(Number(q.physicsMs||0)>budget*0.4)issues.push('PHYSICS_HOT');
  if(Number(q.renderMs||0)>budget*0.5)issues.push('RENDER_HOT');
  if(Number(q.assetMs||0)>budget*0.25)issues.push('ASSET_HOT');
  if(Number(q.drawCalls||0)>Number(q.drawCallBudget||Infinity))issues.push('DRAW_CALL_BUDGET');
  if(issues.indexOf('FRAME_BUDGET_EXCEEDED')>=0)hints.push('Use the frame diagnostics counters to locate the dominant stage before optimizing blindly.');
  if(issues.indexOf('RENDER_HOT')>=0)hints.push('Check culling, batching, texture atlas reuse and render state changes.');
  if(issues.indexOf('PHYSICS_HOT')>=0)hints.push('Check broad-phase candidate count, fixed-step size and collision layer filtering.');
  return{ok:issues.length===0,issues:issues,hints:hints};
}
function getDeveloperPainPointReportV37(){
  return{
    version:37,
    solved:[
      {id:'DX125',problem:'Global mutable game state becomes hard to reason about.',solution:'StateStore adds observable, transactional state with bounded undo and checksums.'},
      {id:'DX126',problem:'Async scene loads complete after a scene has already changed.',solution:'SceneRouter uses generation tokens so stale transitions can be rejected.'},
      {id:'DX127',problem:'Asset failures surface only after players reach a broken scene.',solution:'AssetPreflight catches duplicate IDs, missing sources/dependencies and obvious bad metadata before runtime.'},
      {id:'DX128',problem:'Debugging means scattering console.log everywhere.',solution:'DebugOverlay centralizes watches, counters, frame records and event breadcrumbs.'},
      {id:'DX129',problem:'Large 2D worlds waste collision queries.',solution:'SpatialHash2D provides an engine-neutral broad-phase accelerator.'},
      {id:'DX130',problem:'Camera code gets duplicated and breaks on bounds/zoom/shake combinations.',solution:'Camera2D unifies follow, bounds, screen/world conversion and shake.'},
      {id:'DX131',problem:'Sound-effect spam destroys important voices.',solution:'AudioVoicePool applies voice count, priority and bus policy.'},
      {id:'DX132',problem:'Feature modules become tightly coupled and difficult to replace.',solution:'PluginRegistry provides explicit dependency ordering and enable/disable boundaries.'},
      {id:'DX133',problem:'Release builds pass locally but fail because of configuration drift.',solution:'BuildDoctor turns release assumptions into executable gates.'},
      {id:'DX134',problem:'Retro constraints are discovered late during porting.',solution:'RetroBudgetValidator validates VRAM/sprite/palette/VBlank-style budgets early.'},
      {id:'DX135',problem:'Fixed-point/retro-like deterministic math gets reimplemented inconsistently.',solution:'FixedMath standardizes quantization and deterministic integer operations.'},
      {id:'DX136',problem:'Menus and gameplay fight over input bindings.',solution:'InputContextStack gives UI/gameplay/editor contexts explicit priority.'},
      {id:'DX137',problem:'Dialogue logic becomes scattered conditionals.',solution:'DialogueRuntime adds serializable branching dialogue state.'},
      {id:'DX138',problem:'Renderer-specific assumptions leak into gameplay code.',solution:'RenderBackendProfile exposes a small capability negotiation contract.'},
      {id:'DX139',problem:'"Nothing appears on screen" wastes hours of debugging.',solution:'diagnoseGameObject explains common scene, asset, transform, culling and render-order failures.'},
      {id:'DX140',problem:'Collision bugs are difficult to classify.',solution:'diagnoseCollision classifies tunneling, masks and callback mistakes.'},
      {id:'DX141',problem:'Input bugs differ by device and focus state.',solution:'diagnoseInput classifies context, binding, focus and pointer issues.'},
      {id:'DX142',problem:'FPS alone does not tell developers why a frame is slow.',solution:'diagnoseFrame separates budget overruns into physics/render/assets/draw-call causes.'}
    ],
    principles:['debuggable-by-default','serializable-state','async-safe-transitions','preflight-before-runtime','bounded-work','explicit-capabilities','retro-budget-first','replaceable-services']
  };
}
