/* V37 process cleanup: remove process-owned handles from all V37 registries. */
function cleanupV37Process(pid){
  var tables=[V37.stores,V37.routers,V37.tasks,V37.preflights,V37.overlays,V37.spatial,V37.cameras,V37.audioVoices,V37.plugins,V37.buildDoctors,V37.budgets,V37.fixedMath,V37.dialogues,V37.inputContexts,V37.renderBackends];
  for(var i=0;i<tables.length;i++){var t=tables[i],k;for(k in t)if(Object.prototype.hasOwnProperty.call(t,k)&&Number(t[k].pid)===Number(pid))delete t[k];}
  return true;
}

/* Wrap the existing cleanup chain once more for V37 resources. */
var cleanupV36Chain=cleanupV36Process;
cleanupV36Process=function(pid){var ok=cleanupV37Process(pid)&&cleanupV36Chain(pid);return ok;};

