function easeV39(name,t){t=Math.max(0,Math.min(1,t));name=v39str(name,'linear');if(name==='quadIn')return t*t;if(name==='quadOut')return 1-(1-t)*(1-t);if(name==='quadInOut')return t<.5?2*t*t:1-Math.pow(-2*t+2,2)/2;if(name==='smooth')return t*t*(3-2*t);if(name==='step')return t<1?0:1;return t;}
