function saveImport(ctx,h,payload,targetSchema){var r=v39own(V39.saves,h),o=typeof payload==='string'?JSON.parse(payload):v39clone(payload),s=parseInt(targetSchema,10)||r.schema,cur=parseInt(o.schema,10)||1;while(cur<s){var fn=r.migrations[cur+'->'+(cur+1)];if(typeof fn!=='function')throw new Error('STATUS_INVALID_STATE: missing migration '+cur+'->'+(cur+1)+'.');o.data=fn(o.data);cur++;}r.schema=s;r.data=o.data;return{schema:r.schema,data:v39clone(r.data)};}
