/* Replay / deterministic input timeline */
function createReplayRecorder(ctx,s){s=s&&typeof s==='object'?s:{};var id=v39id(),r={handle:id,pid:v39ctx(ctx),seed:parseInt(s.seed,10)||1,frame:0,events:[],recording:true,index:0};V39.replays[id]=r;return{handle:id,seed:r.seed};}
function replayRecord(ctx,h,input){var r=v39own(V39.replays,h);if(!r.recording)return false;r.events.push({frame:r.frame,input:v39clone(input)});return r.events.length;}
