/* Grid pathfinding (A*) */
function createPathGrid(ctx,s){s=s&&typeof s==='object'?s:{};var id=v39id(),r={handle:id,pid:v39ctx(ctx),w:Math.max(1,parseInt(s.width,10)||1),h:Math.max(1,parseInt(s.height,10)||1),blocked:{}};V39.nav[id]=r;return{handle:id,width:r.w,height:r.h};}
function pathSetBlocked(ctx,h,x,y,b){var r=v39own(V39.nav,h),k=(parseInt(x,10)||0)+','+(parseInt(y,10)||0);if(b)r.blocked[k]=true;else delete r.blocked[k];return true;}
function pathFind(ctx,h,sx,sy,gx,gy){var r=v39own(V39.nav,h),start=(parseInt(sx,10)||0)+','+(parseInt(sy,10)||0),goal=(parseInt(gx,10)||0)+','+(parseInt(gy,10)||0);if(r.blocked[start]||r.blocked[goal])return[];var open=[{x:parseInt(sx,10)||0,y:parseInt(sy,10)||0,g:0,f:0}],came={},best={};best[start]=0;function hcost(x,y){return Math.abs(x-(parseInt(gx,10)||0))+Math.abs(y-(parseInt(gy,10)||0));}while(open.length){open.sort(function(a,b){return a.f-b.f;});var c=open.shift(),ck=c.x+','+c.y;if(ck===goal){var path=[];while(c){path.push({x:c.x,y:c.y});c=came[c.x+','+c.y];}return path.reverse();}var ns=[[1,0],[-1,0],[0,1],[0,-1]];for(var i=0;i<ns.length;i++){var nx=c.x+ns[i][0],ny=c.y+ns[i][1],k=nx+','+ny;if(nx<0||ny<0||nx>=r.w||ny>=r.h||r.blocked[k])continue;var ng=c.g+1;if(best[k]===undefined||ng<best[k]){best[k]=ng;came[k]=c;open.push({x:nx,y:ny,g:ng,f:ng+hcost(nx,ny)});}}}return[];}
