/* Object pool */
function createObjectPoolV39(ctx,s){s=s&&typeof s==='object'?s:{};var id=v39id(),r={handle:id,pid:v39ctx(ctx),name:v39str(s.name,'Pool'+id),capacity:Math.max(1,parseInt(s.capacity,10)||64),free:[],used:{},factory:v39clone(s.factory||null),next:1};V39.pools[id]=r;return{handle:id,capacity:r.capacity};}
function poolAcquire(ctx,h,seed){var r=v39own(V39.pools,h),id='o'+r.next++;if(Object.keys(r.used).length>=r.capacity)return null;var o=v39clone(seed||r.factory||{});o.__poolId=id;o.active=true;r.used[id]=o;return{handle:id,value:v39clone(o)};}
