/* Physics query helper - engine-neutral geometry, no hidden physics backend */
function physicsAabbOverlap(a,b){return !(a.x+a.w<b.x||a.x>b.x+b.w||a.y+a.h<b.y||a.y>b.y+b.h);}
function createPhysicsQuery(ctx,s){s=s&&typeof s==='object'?s:{};var id=v39id(),r={handle:id,pid:v39ctx(ctx),bodies:{},gravity:v39clone(s.gravity||{x:0,y:0})};V39.physics[id]=r;return{handle:id};}
