function physicsRaycast(ctx,h,origin,dir,maxDist){var r=v39own(V39.physics,h),o=origin||{x:0,y:0},d=dir||{x:1,y:0},m=Math.max(0,v39num(maxDist,Infinity)),hits=[];Object.keys(r.bodies).forEach(function(k){var b=r.bodies[k],a=b.aabb;if(!a)return;var px=o.x,py=o.y,tx=(a.x-px)/(d.x||1e-9),ty=(a.y-py)/(d.y||1e-9),t=Math.min(Math.abs(tx),Math.abs(ty));if(t>=0&&t<=m)hits.push({id:k,distance:t});});hits.sort(function(a,b){return a.distance-b.distance;});return hits;}
